type Status = "not_started" | "in_progress" | "ready" | "delivered";
type View = "today" | "orders" | "add" | "products" | "new_product" | "profile" | "summary" | "settings";
type Product = { id: string; name: string; price: number; leadTime: number; color: string; image?: string; archived?: boolean };
type Order = { id: string; customer: string; product: string; due: string; dueDate?: string; total: number; status: Status; createdAt: string; notes?: string; synced?: boolean };
type Message = { type: "success" | "error"; text: string };
type Expense = { id: string; label: string; amount: number; date: string };
type BusinessProfile = { logo?: string; ownerName?: string };
type Settings = { workingDays: number; reminderTime: string };
type StoredStudioState = { orders?: Order[]; products?: Product[]; expenses?: Expense[]; settings?: Settings; snoozed?: string[]; businessProfile?: Pick<BusinessProfile, "ownerName" | "logo"> };

